from pwn import *

def traverse_char(c, tree):
    pos = 0
    while True:
        if tree[pos] == ord(c):
            return pos
        elif tree[pos] == 0xffffffff:  # -1 in unsigned int
            return -1
        elif ord(c) < tree[pos]:
            pos = 2 * pos + 1
        else:
            pos = 2 * pos + 2
        if pos >= 32:
            return -1

# Binary tree stored in memory (from hexdump)
tree = [
    0x77, 0x66, 0x7b, 0x5f, 0x6e, 0x79, 0x7d,  # w, f, {, _, n, y, }
    0xff, 0x62, 0x6c, 0x72, 0xff, 0xff, 0xff, 0xff,  # b, l, r
    0xff, 0x61, 0x65, 0x69, 0xff, 0x6f, 0x74, 0xff,  # a, e, i, o, t
    0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x67, 0xff,  # g
]

# Expected traversal sequence from data section
expected = [
    0x01, 0x09, 0x11, 0x27, 0x02, 0x00, 0x12, 0x03,
    0x08, 0x12, 0x09, 0x12, 0x11, 0x01, 0x03, 0x13,
    0x04, 0x03, 0x05, 0x15, 0x2e
]

def find_char_for_index(target_idx):
    for i in range(32):
        if tree[i] == 0xffffffff:
            continue
        val = chr(tree[i])
        pos = traverse_char(val, tree)
        if pos == target_idx:
            return val
    return None

print("Building flag...")
flag = ""
for idx in expected:
    if idx >= 32:
        continue
    c = find_char_for_index(idx)
    if c:
        flag += c
        print(f"Found char '{c}' for index {idx}")
    else:
        print(f"No char found for index {idx}")

print(f"\nConstructed flag: {flag}")

# Test the flag
